function makeCounter() {
  let count = 0;
  return function () {
    count += 1;
    return count;
  };
}
const c = makeCounter();
c(); // 1
c(); // 2

function createBankAccount(opening) {
  let balance = opening;
  return {
    deposit(n) { balance += n; },
    getBalance() { return balance; },
  };
}
const acct = createBankAccount(100);
// balance is not accessible directly

