function attach(el) {
  const huge = new Array(1e6).fill('*');
  el.addEventListener('click', () => {
    console.log(huge[0]); // retains huge for listener lifetime
  });
}

function multiplyBy(factor) {
  return (n) => n * factor;
}
const double = multiplyBy(2);
double(5); // 10

function partial(fn, ...preset) {
  return (...rest) => fn(...preset, ...rest);
}

function createWatcher(getCount) {
  // prefer reading via getter/ref to avoid stale snapshots
  setInterval(() => console.log(getCount()), 1000);
}
